function validate([paragraph, banned]) {
  if (typeof paragraph !== 'string' || paragraph.length < 1 || paragraph.length > 1000) return 'paragraph must have 1 to 1000 characters.';
  if (!/^[A-Za-z !?',;.]*$/.test(paragraph)) return "paragraph may only contain letters, spaces and !?',;.";
  if (!Array.isArray(banned) || banned.length > 100) return 'banned may hold at most 100 words.';
  for (const w of banned) {
    if (typeof w !== 'string' || !/^[a-z]{1,10}$/.test(w)) return 'Each banned word is 1 to 10 lowercase letters.';
  }
  const blocked = new Set(banned);
  const counts = new Map();
  for (const w of paragraph.toLowerCase().split(/[^a-z]+/)) {
    if (w && !blocked.has(w)) counts.set(w, (counts.get(w) || 0) + 1);
  }
  if (counts.size === 0) return 'At least one word must not be banned.';
  let top = 0;
  let ties = 0;
  for (const v of counts.values()) {
    if (v > top) { top = v; ties = 1; } else if (v === top) ties++;
  }
  if (ties !== 1) return 'Exactly one non-banned word must be the most frequent.';
  return null;
}

