function mostCommonWord(paragraph, banned) {
  const bannedSet = new Set(banned);
  const words = paragraph.toLowerCase().split(/[^a-z]+/);
  const count = new Map();
  let best = '';
  let bestCount = 0;
  for (const word of words) {
    if (word === '' || bannedSet.has(word)) {
      continue;
    }
    const seen = (count.get(word) || 0) + 1;
    count.set(word, seen);
    if (seen > bestCount) {
      best = word;
      bestCount = seen;
    }
  }
  return best;
}

