function mostCommonWord(paragraph, banned) {
  // Cut the text into words by hand, then count each distinct word with a full scan.
  const isLetter = (ch) => (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
  const list = [];
  let current = '';
  for (const ch of paragraph + ' ') {
    if (isLetter(ch)) {
      current += ch.toLowerCase();
    } else if (current !== '') {
      list.push(current);
      current = '';
    }
  }
  let answer = null;
  let answerCount = -1;
  for (const candidate of list) {
    if (banned.includes(candidate)) continue;
    let times = 0;
    for (const other of list) if (other === candidate) times++;
    if (times > answerCount) {
      answer = candidate;
      answerCount = times;
    }
  }
  return answer;
}

