function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const symbols = "!?',;.";
  const makeWord = (maxLen) => {
    let w = '';
    const len = 1 + pick(maxLen);
    for (let i = 0; i < len; i++) w += letters[pick(letters.length)];
    return w;
  };
  for (;;) {
    const vocabSize = size === 'large' ? 30 + pick(60) : 2 + pick(5);
    const vocab = [];
    for (let i = 0; i < vocabSize; i++) vocab.push(makeWord(size === 'large' ? 8 : 3));
    const limit = size === 'large' ? 1000 : 1 + pick(40);
    let paragraph = '';
    if (rand() < 0.2) paragraph += symbols[pick(symbols.length)];
    for (;;) {
      // Skewed choice so a few words repeat often.
      let word = vocab[Math.floor(vocabSize * rand() * rand())];
      word = word.split('').map(ch => (rand() < 0.3 ? ch.toUpperCase() : ch)).join('');
      const r = rand();
      const sep = r < 0.6 ? ' ' : r < 0.85 ? symbols[pick(symbols.length)] + ' ' : symbols[pick(symbols.length)];
      if (paragraph.length + word.length > limit) break;
      paragraph += word;
      if (paragraph.length + sep.length > limit) break;
      paragraph += sep;
    }
    if (paragraph.length === 0) continue;
    const banned = [];
    const bannedCount = size === 'large' ? pick(101) : pick(4);
    for (let i = 0; i < bannedCount; i++) {
      banned.push(rand() < 0.6 ? vocab[pick(vocabSize)].slice(0, 10) : makeWord(size === 'large' ? 10 : 3));
    }
    const words = paragraph.toLowerCase().split(/[^a-z]+/).filter(w => w && !banned.includes(w));
    const counts = new Map();
    for (const w of words) counts.set(w, (counts.get(w) || 0) + 1);
    if (counts.size === 0) continue;
    const top = Math.max(...counts.values());
    if ([...counts.values()].filter(v => v === top).length !== 1) continue;
    return [paragraph, banned];
  }
}
